package solution

import (
	"fmt"
	"math/big"
	"reflect"
	"strconv"
	"strings"
	"testing"
	"time"
)

func requireDecodeError(t *testing.T, data string) {
	t.Helper()
	got, err := DecodeReleasePage([]byte(data))
	if err == nil {
		t.Fatalf("DecodeReleasePage(%q) unexpectedly succeeded: %#v", data, got)
	}
	if !reflect.DeepEqual(got, ReleasePage{}) {
		t.Fatalf("DecodeReleasePage(%q) returned non-zero page on error: %#v", data, got)
	}
}

func TestDecodeReleasePageValid(t *testing.T) {
	data := []byte(" \n{\"next_cursor\":17,\"items\":[{\"published\":\"2024-02-29\",\"name\":\"Alpha\",\"id\":2},{\"id\":7,\"name\":\"  \",\"published\":\"1999-12-31\"}]}\t ")
	original := append([]byte(nil), data...)

	got, err := DecodeReleasePage(data)
	if err != nil {
		t.Fatalf("DecodeReleasePage returned error: %v", err)
	}
	want := ReleasePage{
		Items: []Release{
			{ID: 2, Name: "Alpha", Published: time.Date(2024, 2, 29, 0, 0, 0, 0, time.UTC)},
			{ID: 7, Name: "  ", Published: time.Date(1999, 12, 31, 0, 0, 0, 0, time.UTC)},
		},
		NextCursor: 17,
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("decoded page mismatch\n got: %#v\nwant: %#v", got, want)
	}
	if !reflect.DeepEqual(data, original) {
		t.Fatalf("input was modified\n got: %q\nwant: %q", data, original)
	}
}

func TestDecodeReleasePageEscapedMemberNames(t *testing.T) {
	data := []byte(`{"\u0069tems":[{"\u0069d":1,"na\u006de":"x","publishe\u0064":"2000-01-01"}],"next_\u0063ursor":0}`)
	got, err := DecodeReleasePage(data)
	if err != nil {
		t.Fatalf("escaped required names should be accepted: %v", err)
	}
	want := ReleasePage{
		Items: []Release{{ID: 1, Name: "x", Published: time.Date(2000, 1, 1, 0, 0, 0, 0, time.UTC)}},
		NextCursor: 0,
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("got %#v, want %#v", got, want)
	}
}

func TestDecodeReleasePageEmptyItemsAreNonNil(t *testing.T) {
	got, err := DecodeReleasePage([]byte(`{"items":[],"next_cursor":-0}`))
	if err != nil {
		t.Fatalf("empty page with negative-zero cursor returned error: %v", err)
	}
	if got.Items == nil {
		t.Fatal("empty items must decode to a non-nil empty slice")
	}
	if len(got.Items) != 0 || got.NextCursor != 0 {
		t.Fatalf("unexpected empty page: %#v", got)
	}
}

func TestDecodeReleasePageDoesNotAliasInput(t *testing.T) {
	data := []byte(`{"items":[{"id":1,"name":"persistent-name","published":"2023-05-06"}],"next_cursor":0}`)
	got, err := DecodeReleasePage(data)
	if err != nil {
		t.Fatalf("DecodeReleasePage returned error: %v", err)
	}
	for i := range data {
		data[i] = 'x'
	}
	if got.Items[0].Name != "persistent-name" {
		t.Fatalf("decoded name aliases input storage: %q", got.Items[0].Name)
	}
	if !got.Items[0].Published.Equal(time.Date(2023, 5, 6, 0, 0, 0, 0, time.UTC)) {
		t.Fatalf("decoded date changed after input mutation: %v", got.Items[0].Published)
	}
}

func TestDecodeReleasePageIntegerBoundaries(t *testing.T) {
	maxInt := int(^uint(0) >> 1)
	input := fmt.Sprintf(`{"items":[{"id":%d,"name":"max","published":"2020-01-01"}],"next_cursor":%d}`, maxInt, maxInt)
	got, err := DecodeReleasePage([]byte(input))
	if err != nil {
		t.Fatalf("native int maximum should be accepted: %v", err)
	}
	if got.Items[0].ID != maxInt || got.NextCursor != maxInt {
		t.Fatalf("integer boundary mismatch: %#v", got)
	}

	overflow := new(big.Int).Add(big.NewInt(int64(maxInt)), big.NewInt(1)).String()
	requireDecodeError(t, fmt.Sprintf(`{"items":[{"id":%s,"name":"x","published":"2020-01-01"}],"next_cursor":0}`, overflow))
	requireDecodeError(t, fmt.Sprintf(`{"items":[],"next_cursor":%s}`, overflow))

	if strconv.IntSize == 32 {
		requireDecodeError(t, `{"items":[],"next_cursor":2147483648}`)
	} else if strconv.IntSize == 64 {
		requireDecodeError(t, `{"items":[],"next_cursor":9223372036854775808}`)
	}
}

func TestDecodeReleasePageRejectsInvalidRootShapes(t *testing.T) {
	cases := []string{
		``,
		` `,
		`null`,
		`[]`,
		`"object"`,
		`1`,
		`true`,
		`{`,
		`{"items":[],"next_cursor":0`,
		`{"items":[],"next_cursor":0} {}`,
		`{"items":[],"next_cursor":0} null`,
		`{"items":[],"next_cursor":0}x`,
	}
	for _, tc := range cases {
		t.Run(strconv.Quote(tc), func(t *testing.T) {
			requireDecodeError(t, tc)
		})
	}
}

func TestDecodeReleasePageRequiresExactRootFields(t *testing.T) {
	cases := []string{
		`{}`,
		`{"items":[]}`,
		`{"next_cursor":0}`,
		`{"items":[],"next_cursor":0,"extra":1}`,
		`{"ITEMS":[],"next_cursor":0}`,
		`{"items":[],"NEXT_CURSOR":0}`,
		`{"Items":[],"next_cursor":0}`,
		`{"items":null,"next_cursor":0}`,
		`{"items":[],"next_cursor":null}`,
	}
	for _, tc := range cases {
		t.Run(tc, func(t *testing.T) {
			requireDecodeError(t, tc)
		})
	}
}

func TestDecodeReleasePageRejectsDuplicateRootMembers(t *testing.T) {
	cases := []string{
		`{"items":[],"items":[],"next_cursor":0}`,
		`{"items":[],"\u0069tems":[],"next_cursor":0}`,
		`{"\u0069tems":[],"items":[],"next_cursor":0}`,
		`{"items":null,"items":[],"next_cursor":0}`,
		`{"items":[],"next_cursor":0,"next_cursor":0}`,
		`{"items":[],"next_cursor":0,"next_\u0063ursor":1}`,
		`{"next_cursor":null,"next_cursor":0,"items":[]}`,
	}
	for _, tc := range cases {
		t.Run(tc, func(t *testing.T) {
			requireDecodeError(t, tc)
		})
	}
}

func TestDecodeReleasePageRequiresExactItemFields(t *testing.T) {
	cases := []string{
		`{"items":[{}],"next_cursor":0}`,
		`{"items":[{"name":"x","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":"x"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":"x","published":"2020-01-01","extra":false}],"next_cursor":0}`,
		`{"items":[{"ID":1,"name":"x","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"Name":"x","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":"x","Published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[null],"next_cursor":0}`,
		`{"items":[1],"next_cursor":0}`,
		`{"items":[[]],"next_cursor":0}`,
	}
	for _, tc := range cases {
		t.Run(tc, func(t *testing.T) {
			requireDecodeError(t, tc)
		})
	}
}

func TestDecodeReleasePageRejectsDuplicateItemMembers(t *testing.T) {
	cases := []string{
		`{"items":[{"id":1,"id":1,"name":"x","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"\u0069d":2,"name":"x","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":null,"id":1,"name":"x","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":"x","name":"x","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":"x","na\u006de":"y","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":"x","published":"2020-01-01","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":"x","published":null,"publishe\u0064":"2020-01-01"}],"next_cursor":0}`,
	}
	for _, tc := range cases {
		t.Run(tc, func(t *testing.T) {
			requireDecodeError(t, tc)
		})
	}
}

func TestDecodeReleasePageDuplicateMemberScopeAndUniqueIDs(t *testing.T) {
	valid := `{"items":[{"id":1,"name":"a","published":"2020-01-01"},{"id":2,"name":"b","published":"2020-01-02"}],"next_cursor":0}`
	got, err := DecodeReleasePage([]byte(valid))
	if err != nil {
		t.Fatalf("same member names in separate item objects must be valid: %v", err)
	}
	if len(got.Items) != 2 || got.Items[0].ID != 1 || got.Items[1].ID != 2 {
		t.Fatalf("item order was not preserved: %#v", got.Items)
	}

	requireDecodeError(t, `{"items":[{"id":1,"name":"a","published":"2020-01-01"},{"id":1,"name":"b","published":"2021-02-03"}],"next_cursor":0}`)
}

func TestDecodeReleasePageRejectsInvalidNumbers(t *testing.T) {
	idValues := []string{`0`, `-0`, `-1`, `1.0`, `1e0`, `1E2`, `"1"`, `true`, `null`}
	for _, value := range idValues {
		t.Run("id_"+value, func(t *testing.T) {
			requireDecodeError(t, `{"items":[{"id":`+value+`,"name":"x","published":"2020-01-01"}],"next_cursor":0}`)
		})
	}

	cursorValues := []string{`-1`, `0.0`, `1.5`, `1e0`, `1E2`, `"0"`, `false`, `null`}
	for _, value := range cursorValues {
		t.Run("cursor_"+value, func(t *testing.T) {
			requireDecodeError(t, `{"items":[],"next_cursor":`+value+`}`)
		})
	}
}

func TestDecodeReleasePageNameValidationAndPreservation(t *testing.T) {
	invalid := []string{
		`{"items":[{"id":1,"name":"","published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":null,"published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":1,"published":"2020-01-01"}],"next_cursor":0}`,
		`{"items":[{"id":1,"name":true,"published":"2020-01-01"}],"next_cursor":0}`,
	}
	for _, tc := range invalid {
		requireDecodeError(t, tc)
	}

	got, err := DecodeReleasePage([]byte(`{"items":[{"id":1,"name":" \t\n ","published":"2020-01-01"},{"id":2,"name":"\u0000","published":"2020-01-02"}],"next_cursor":0}`))
	if err != nil {
		t.Fatalf("non-empty blank/control names should be accepted: %v", err)
	}
	if got.Items[0].Name != " \t\n " || got.Items[1].Name != "\x00" {
		t.Fatalf("names were normalized or not preserved: %#v", got.Items)
	}
}

func TestDecodeReleasePageDateValidation(t *testing.T) {
	validDates := []string{"0001-01-01", "2000-02-29", "9999-12-31"}
	for i, date := range validDates {
		t.Run("valid_"+date, func(t *testing.T) {
			input := fmt.Sprintf(`{"items":[{"id":%d,"name":"x","published":%q}],"next_cursor":0}`, i+1, date)
			got, err := DecodeReleasePage([]byte(input))
			if err != nil {
				t.Fatalf("valid date %q rejected: %v", date, err)
			}
			if got.Items[0].Published.Format("2006-01-02") != date {
				t.Fatalf("date round trip mismatch: got %q, want %q", got.Items[0].Published.Format("2006-01-02"), date)
			}
			if got.Items[0].Published.Location() != time.UTC || got.Items[0].Published.Hour() != 0 {
				t.Fatalf("date is not midnight UTC: %v", got.Items[0].Published)
			}
		})
	}

	invalidDates := []string{
		"", "2023-02-29", "2024-02-30", "2023-04-31", "2023-00-01", "2023-13-01",
		"2023-01-00", "2023-01-32", "2023-1-01", "2023-01-1", "23-01-01",
		"02023-01-01", "+2023-01-01", "2023-01-01T00:00:00Z", "2023-01-01 ", " 2023-01-01",
	}
	for _, date := range invalidDates {
		t.Run("invalid_"+date, func(t *testing.T) {
			input := fmt.Sprintf(`{"items":[{"id":1,"name":"x","published":%q}],"next_cursor":0}`, date)
			requireDecodeError(t, input)
		})
	}

	for _, value := range []string{`null`, `20200101`, `true`, `[]`, `{}`} {
		requireDecodeError(t, `{"items":[{"id":1,"name":"x","published":`+value+`}],"next_cursor":0}`)
	}
}

func TestDecodeReleasePageErrorAlwaysReturnsCompleteZeroValue(t *testing.T) {
	cases := []string{
		`{"items":[{"id":1,"name":"first","published":"2020-01-01"},{"id":2,"name":"second","published":"bad"}],"next_cursor":9}`,
		`{"items":[{"id":1,"name":"first","published":"2020-01-01"}],"next_cursor":-1}`,
		`{"items":[{"id":1,"name":"first","published":"2020-01-01"}],"next_cursor":9,"unknown":true}`,
		`{"items":[{"id":1,"name":"first","published":"2020-01-01"}],"next_cursor":9} []`,
	}
	for _, tc := range cases {
		requireDecodeError(t, tc)
	}
}

func TestDecodeReleasePageDeterministicAcrossCalls(t *testing.T) {
	input := []byte(`{"items":[{"id":3,"name":"stable","published":"2022-08-09"}],"next_cursor":4}`)
	first, err := DecodeReleasePage(input)
	if err != nil {
		t.Fatalf("first decode failed: %v", err)
	}
	second, err := DecodeReleasePage(input)
	if err != nil {
		t.Fatalf("second decode failed: %v", err)
	}
	if !reflect.DeepEqual(first, second) {
		t.Fatalf("repeated decodes differ: first=%#v second=%#v", first, second)
	}
	if strings.TrimSpace(first.Items[0].Name) != "stable" {
		t.Fatalf("unexpected decoded content: %#v", first)
	}
}

