import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"time"
)

type Release struct {
	ID        int
	Name      string
	Published time.Time
}

type ReleasePage struct {
	Items      []Release
	NextCursor int
}

func DecodeReleasePage(data []byte) (ReleasePage, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	page, err := decodePage(dec)
	if err != nil {
		return ReleasePage{}, fmt.Errorf("decode release page: %w", err)
	}

	var trailing json.RawMessage
	if err := dec.Decode(&trailing); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("trailing JSON value")
		}
		return ReleasePage{}, fmt.Errorf("decode release page: %w", err)
	}
	return page, nil
}

func decodePage(dec *json.Decoder) (ReleasePage, error) {
	if err := expectDelim(dec, '{'); err != nil {
		return ReleasePage{}, err
	}

	items := make([]Release, 0)
	var nextCursor int
	seenMembers := make(map[string]struct{}, 2)
	haveItems := false
	haveCursor := false

	for dec.More() {
		name, err := memberName(dec)
		if err != nil {
			return ReleasePage{}, err
		}
		if _, exists := seenMembers[name]; exists {
			return ReleasePage{}, fmt.Errorf("duplicate root member %q", name)
		}
		seenMembers[name] = struct{}{}

		switch name {
		case "items":
			items, err = decodeItems(dec)
			if err != nil {
				return ReleasePage{}, err
			}
			haveItems = true
		case "next_cursor":
			if err := decodeNonNull(dec, &nextCursor); err != nil {
				return ReleasePage{}, fmt.Errorf("invalid next_cursor: %w", err)
			}
			haveCursor = true
		default:
			return ReleasePage{}, fmt.Errorf("unknown root member %q", name)
		}
	}

	if err := expectDelim(dec, '}'); err != nil {
		return ReleasePage{}, err
	}
	if !haveItems || !haveCursor {
		return ReleasePage{}, fmt.Errorf("items and next_cursor are required")
	}
	if nextCursor < 0 {
		return ReleasePage{}, fmt.Errorf("next_cursor cannot be negative")
	}
	return ReleasePage{Items: items, NextCursor: nextCursor}, nil
}

