#[path = "solution.rs"]
mod solution;

use solution::extract_action_label;

#[test]
fn extracts_first_exact_action_label_from_valid_input() {
    let markup = concat!(
        "[attribute kind=\"other\"]ignored[/attribute]",
        "[attribute kind=\"action-label\"]Launch 🚀\nnow[/attribute]",
        "[attribute kind=\"action-label\"]later[/attribute]"
    );
    assert_eq!(extract_action_label(markup), Some("Launch 🚀\nnow".to_string()));
}

#[test]
fn handles_empty_input_empty_kinds_and_empty_matching_values() {
    assert_eq!(extract_action_label(""), None);
    assert_eq!(extract_action_label("[attribute kind=\"\"][/attribute]"), None);
    assert_eq!(
        extract_action_label("[attribute kind=\"action-label\"][/attribute]"),
        Some(String::new())
    );
}

#[test]
fn matching_is_exact_and_case_sensitive() {
    let markup = concat!(
        "[attribute kind=\"Action-Label\"]wrong[/attribute]",
        "[attribute kind=\"action-label-extra\"]wrong[/attribute]",
        "[attribute kind=\"action-label\"]right[/attribute]"
    );
    assert_eq!(extract_action_label(markup), Some("right".to_string()));
}

#[test]
fn accepts_allowed_utf8_and_punctuation_without_closing_brackets() {
    let markup = "[attribute kind=\"action-label\"]é漢字 [ open, quotes \" and :\nsecond line[/attribute]";
    assert_eq!(
        extract_action_label(markup),
        Some("é漢字 [ open, quotes \" and :\nsecond line".to_string())
    );
}

#[test]
fn rejects_forbidden_closing_bracket_in_kind_or_value() {
    assert_eq!(
        extract_action_label("[attribute kind=\"bad]kind\"]value[/attribute]"),
        None
    );
    assert_eq!(
        extract_action_label("[attribute kind=\"action-label\"]bad]value[/attribute]"),
        None
    );
}

#[test]
fn validates_attributes_after_a_successful_match() {
    let bad_kind = concat!(
        "[attribute kind=\"action-label\"]first[/attribute]",
        "[attribute kind=\"bad]kind\"]later[/attribute]"
    );
    let bad_value = concat!(
        "[attribute kind=\"action-label\"]first[/attribute]",
        "[attribute kind=\"other\"]later]value[/attribute]"
    );
    let truncated = concat!(
        "[attribute kind=\"action-label\"]first[/attribute]",
        "[attribute kind=\"other\"]unfinished"
    );

    assert_eq!(extract_action_label(bad_kind), None);
    assert_eq!(extract_action_label(bad_value), None);
    assert_eq!(extract_action_label(truncated), None);
}

#[test]
fn rejects_malformed_or_separated_markup() {
    assert_eq!(extract_action_label("plain text"), None);
    assert_eq!(extract_action_label("[attribute kind='action-label']x[/attribute]"), None);
    assert_eq!(extract_action_label("[attribute kind=\"action-label\" ]x[/attribute]"), None);
    assert_eq!(
        extract_action_label(concat!(
            "[attribute kind=\"other\"]x[/attribute]",
            " ",
            "[attribute kind=\"action-label\"]y[/attribute]"
        )),
        None
    );
}

#[test]
fn borrowed_input_is_not_mutated() {
    let markup = String::from("[attribute kind=\"action-label\"]stable[/attribute]");
    let original = markup.clone();
    assert_eq!(extract_action_label(&markup), Some("stable".to_string()));
    assert_eq!(markup, original);
}

