#[path = "solution.rs"]
mod solution;

use solution::{FocusRing, Overlay, Page, UiState};

#[test]
fn empty_ring_stays_at_zero() {
    let mut ring = FocusRing::new(0);
    assert_eq!(ring.index(), 0);
    ring.next();
    ring.previous();
    assert_eq!(ring.index(), 0);
}

#[test]
fn ordinary_ring_wraps_in_both_directions() {
    let mut ring = FocusRing::new(3);
    ring.previous();
    assert_eq!(ring.index(), 2);
    ring.next();
    assert_eq!(ring.index(), 0);
    ring.next();
    ring.next();
    ring.next();
    assert_eq!(ring.index(), 0);
}

#[test]
fn maximum_logical_length_does_not_overflow() {
    let mut ring = FocusRing::new(usize::MAX);

    ring.next();
    assert_eq!(ring.index(), 1);
    ring.previous();
    assert_eq!(ring.index(), 0);

    ring.previous();
    assert_eq!(ring.index(), usize::MAX - 1);
    ring.next();
    assert_eq!(ring.index(), 0);
}

#[test]
fn resizing_clamps_or_resets_and_remains_navigable() {
    let mut ring = FocusRing::new(5);
    ring.previous();
    assert_eq!(ring.index(), 4);

    ring.set_len(3);
    assert_eq!(ring.index(), 2);
    ring.set_len(10);
    assert_eq!(ring.index(), 2);
    ring.set_len(0);
    assert_eq!(ring.index(), 0);
    ring.next();
    ring.previous();
    assert_eq!(ring.index(), 0);

    ring.set_len(2);
    assert_eq!(ring.index(), 0);
    ring.previous();
    assert_eq!(ring.index(), 1);
}

#[test]
fn navigation_changes_only_page_and_preserves_overlay_and_focus() {
    let mut state = UiState::new(4);
    state.focus.next();
    state.overlay = Overlay::Filter;
    let focus_before = state.focus.clone();

    state.navigate(Page::Queue);

    assert_eq!(state.page, Page::Queue);
    assert_eq!(state.overlay, Overlay::Filter);
    assert_eq!(state.focus, focus_before);
}

