#[path = "solution.rs"]
mod solution;

use solution::{IdentityBook, IdentityError, Permission};

#[test]
fn new_and_default_are_independent_and_start_ids_at_one() {
    let mut from_new = IdentityBook::new();
    let mut from_default = IdentityBook::default();

    assert!(from_new.is_empty());
    assert!(from_default.is_empty());
    assert_eq!(
        from_new.add("a@example.com".to_string(), "a-secret".to_string(), Permission::Reader),
        Ok(1)
    );
    assert_eq!(
        from_default.add("b@example.com".to_string(), "b-secret".to_string(), Permission::Owner),
        Ok(1)
    );
    assert_eq!(from_new.len(), 1);
    assert_eq!(from_default.len(), 1);
    assert!(!from_new.authenticate("b@example.com", "b-secret"));
    assert!(!from_default.authenticate("a@example.com", "a-secret"));
}

#[test]
fn validation_order_and_failed_additions_do_not_consume_ids() {
    let mut book = IdentityBook::default();

    assert_eq!(
        book.add(String::new(), String::new(), Permission::Owner),
        Err(IdentityError::EmptyAddress)
    );
    assert_eq!(
        book.add("first".to_string(), String::new(), Permission::Owner),
        Err(IdentityError::EmptySecret)
    );
    assert!(book.is_empty());

    assert_eq!(
        book.add("first".to_string(), "secret-1".to_string(), Permission::Reader),
        Ok(1)
    );
    assert_eq!(
        book.add("first".to_string(), String::new(), Permission::Owner),
        Err(IdentityError::EmptySecret)
    );
    assert_eq!(
        book.add("first".to_string(), "different".to_string(), Permission::Owner),
        Err(IdentityError::DuplicateAddress)
    );
    assert_eq!(book.len(), 1);
    assert_eq!(book.permission("first"), Some(Permission::Reader));
    assert!(book.authenticate("first", "secret-1"));

    assert_eq!(
        book.add("second".to_string(), "secret-2".to_string(), Permission::Owner),
        Ok(2)
    );
}

#[test]
fn authentication_requires_exact_address_and_secret() {
    let mut book = IdentityBook::new();
    book.add("User@example.com".to_string(), "CaseSensitive".to_string(), Permission::Owner).unwrap();

    assert!(book.authenticate("User@example.com", "CaseSensitive"));
    assert!(!book.authenticate("user@example.com", "CaseSensitive"));
    assert!(!book.authenticate("User@example.com", "casesensitive"));
    assert!(!book.authenticate("User@example.com", ""));
    assert!(!book.authenticate("", "CaseSensitive"));
    assert!(!book.authenticate("unknown", "CaseSensitive"));
}

#[test]
fn permission_lookup_is_exact_and_observers_are_stable() {
    let mut book = IdentityBook::new();
    book.add("alpha".to_string(), "one".to_string(), Permission::Reader).unwrap();
    book.add("Alpha".to_string(), "two".to_string(), Permission::Owner).unwrap();

    assert_eq!(book.permission("alpha"), Some(Permission::Reader));
    assert_eq!(book.permission("Alpha"), Some(Permission::Owner));
    assert_eq!(book.permission("ALPHA"), None);
    assert_eq!(book.permission(""), None);

    for _ in 0..3 {
        assert_eq!(book.len(), 2);
        assert!(!book.is_empty());
        assert!(book.authenticate("alpha", "one"));
        assert_eq!(book.permission("Alpha"), Some(Permission::Owner));
    }
    assert_eq!(book.len(), 2);
}

#[test]
fn blank_but_nonempty_credentials_are_not_normalized() {
    let mut book = IdentityBook::default();
    assert_eq!(
        book.add(" ".to_string(), "\t".to_string(), Permission::Reader),
        Ok(1)
    );
    assert!(book.authenticate(" ", "\t"));
    assert_eq!(book.permission(" "), Some(Permission::Reader));
}

