'use strict';

const kinds = new Set(['lab', 'kitchen', 'garden', 'studio']);
const nonEmpty = value => typeof value === 'string' && value.length > 0;

function hasExactOwnKeys(value, expected) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const keys = Reflect.ownKeys(value);
  return keys.length === expected.length &&
    keys.every(key => typeof key === 'string' && expected.includes(key)) &&
    expected.every(key => Object.prototype.hasOwnProperty.call(value, key));
}

function createWorkshopRegistry(initialHosts = []) {
  if (!Array.isArray(initialHosts)) throw new TypeError('initialHosts must be an array');

  const hosts = new Map();
  for (const host of initialHosts) {
    if (!hasExactOwnKeys(host, ['id', 'name']) || !nonEmpty(host.id) || !nonEmpty(host.name)) {
      throw new TypeError('invalid host');
    }
    if (hosts.has(host.id)) throw new RangeError('duplicate host');
    hosts.set(host.id, { id: host.id, name: host.name });
  }

  const workshops = [];
  const names = new Set();

  function copyWorkshop(workshop) {
    return {
      name: workshop.name,
      kind: workshop.kind,
      address: workshop.address,
      host: { id: workshop.host.id, name: workshop.host.name }
    };
  }

  function register(input) {
    if (!hasExactOwnKeys(input, ['name', 'kind', 'address', 'host']) ||
        !nonEmpty(input.name) || !kinds.has(input.kind) || !nonEmpty(input.address)) {
      throw new TypeError('invalid workshop');
    }

    const normalizedName = input.name.trim().toLowerCase();
    if (names.has(normalizedName)) throw new RangeError('duplicate workshop');

    let resolvedHost;
    let pendingHost = null;

    if (hasExactOwnKeys(input.host, ['id'])) {
      if (!nonEmpty(input.host.id) || !hosts.has(input.host.id)) {
        throw new TypeError('invalid host selection');
      }
      resolvedHost = hosts.get(input.host.id);
    } else if (hasExactOwnKeys(input.host, ['newHost'])) {
      const candidate = input.host.newHost;
      if (!hasExactOwnKeys(candidate, ['id', 'name']) ||
          !nonEmpty(candidate.id) || !nonEmpty(candidate.name)) {
        throw new TypeError('invalid new host');
      }
      if (hosts.has(candidate.id)) throw new RangeError('duplicate host');
      pendingHost = { id: candidate.id, name: candidate.name };
