'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['createWorkshopRegistry']);
assert.strictEqual(typeof api.createWorkshopRegistry, 'function');
const { createWorkshopRegistry } = api;

function expectTypeError(fn) {
  assert.throws(fn, TypeError);
}

function expectRangeError(fn) {
  assert.throws(fn, RangeError);
}

function hiddenHost(id, name) {
  const host = {};
  Object.defineProperty(host, 'id', { value: id, enumerable: false, writable: true });
  Object.defineProperty(host, 'name', { value: name, enumerable: false, writable: true });
  return host;
}

// Defaults, exact returned API, and empty state.
const empty = createWorkshopRegistry();
assert.deepStrictEqual(Reflect.ownKeys(empty).sort(), ['list', 'register']);
assert.strictEqual(typeof empty.register, 'function');
assert.strictEqual(typeof empty.list, 'function');
assert.deepStrictEqual(empty.list(), []);
assert.notStrictEqual(empty.list(), empty.list());

// Initial hosts accept non-enumerable fields and unusual prototypes, and are copied.
const firstHost = hiddenHost(' H-1 ', '  Ada  ');
const protoHost = Object.create({ inheritedExtra: true });
protoHost.id = 'h2';
protoHost.name = 'Grace';
const registry = createWorkshopRegistry([firstHost, protoHost]);
firstHost.id = 'changed';
firstHost.name = 'changed';
protoHost.name = 'changed';

const workshopProto = { inheritedExtra: 'allowed' };
const workshop = Object.create(workshopProto);
workshop.name = '  Intro Lab  ';
workshop.kind = 'lab';
workshop.address = ' Room 1 ';
workshop.host = Object.assign(Object.create({ inheritedExtra: 1 }), { id: ' H-1 ' });
const created = registry.register(workshop);
assert.deepStrictEqual(created, {
  name: '  Intro Lab  ',
  kind: 'lab',
  address: ' Room 1 ',
  host: { id: ' H-1 ', name: '  Ada  ' }
});

// Inputs and returned snapshots cannot mutate stored state.
workshop.name = 'mutated input';
workshop.host.id = 'h2';
created.name = 'mutated output';
created.host.id = 'mutated output host';
created.host.name = 'mutated output host name';
const listedOnce = registry.list();
assert.deepStrictEqual(listedOnce, [{
  name: '  Intro Lab  ',
  kind: 'lab',
  address: ' Room 1 ',
  host: { id: ' H-1 ', name: '  Ada  ' }
}]);
listedOnce.push({});
listedOnce[0].address = 'changed';
listedOnce[0].host.name = 'changed';
assert.deepStrictEqual(registry.list(), [{
  name: '  Intro Lab  ',
  kind: 'lab',
  address: ' Room 1 ',
  host: { id: ' H-1 ', name: '  Ada  ' }
}]);
assert.notStrictEqual(registry.list()[0], registry.list()[0]);
assert.notStrictEqual(registry.list()[0].host, registry.list()[0].host);

// Every kind is accepted exactly, and registration order is retained.
for (const [name, kind] of [['Kitchen Work', 'kitchen'], ['Garden Work', 'garden'], ['Studio Work', 'studio']]) {
  registry.register({ name, kind, address: 'x', host: { id: 'h2' } });
}
assert.deepStrictEqual(registry.list().map(x => x.name), [
  '  Intro Lab  ', 'Kitchen Work', 'Garden Work', 'Studio Work'
]);

// Name uniqueness uses trim + lowercase while stored strings remain verbatim.
expectRangeError(() => registry.register({
  name: ' intro LAB ', kind: 'lab', address: 'elsewhere', host: { id: 'h2' }
}));
assert.strictEqual(registry.list().length, 4);

// Blank, but non-empty, strings are valid and blank names collide after normalization.
const blanks = createWorkshopRegistry([{ id: ' ', name: '\t' }]);
assert.deepStrictEqual(blanks.register({
  name: ' ', kind: 'garden', address: '\n', host: { id: ' ' }
}), {
  name: ' ', kind: 'garden', address: '\n', host: { id: ' ', name: '\t' }
});
expectRangeError(() => blanks.register({
  name: '\t\n', kind: 'garden', address: 'x', host: { id: ' ' }
}));

// A new host is resolved, copied, and immediately usable by exact ID.
const newHostInput = { id: 'NewID', name: 'New Name' };
const withNew = registry.register({
  name: 'New-host workshop', kind: 'lab', address: 'A', host: { newHost: newHostInput }
});
newHostInput.id = 'altered';
newHostInput.name = 'altered';
assert.deepStrictEqual(withNew.host, { id: 'NewID', name: 'New Name' });
assert.deepStrictEqual(registry.register({
  name: 'Uses new host', kind: 'studio', address: 'B', host: { id: 'NewID' }
}).host, { id: 'NewID', name: 'New Name' });
expectTypeError(() => registry.register({
  name: 'Wrong case host', kind: 'lab', address: 'x', host: { id: 'newid' }
}));

// Duplicate new-host IDs are RangeErrors and do not add workshops.
const beforeDuplicateHost = registry.list().length;
expectRangeError(() => registry.register({
  name: 'Must not persist', kind: 'lab', address: 'x',
  host: { newHost: { id: 'NewID', name: 'Another' } }
}));
assert.strictEqual(registry.list().length, beforeDuplicateHost);
registry.register({ name: 'Must not persist', kind: 'lab', address: 'x', host: { id: 'NewID' } });

// A duplicate workshop name must not partially add its proposed host.
expectRangeError(() => registry.register({
  name: '  MUST NOT PERSIST  ', kind: 'garden', address: 'x',
  host: { newHost: { id: 'orphan', name: 'Orphan' } }
}));
expectTypeError(() => registry.register({
  name: 'Cannot use orphan', kind: 'lab', address: 'x', host: { id: 'orphan' }
}));
registry.register({
  name: 'Can create orphan now', kind: 'lab', address: 'x',
  host: { newHost: { id: 'orphan', name: 'Orphan' } }
});

// Malformed registration must also be atomic with respect to a proposed host.
expectTypeError(() => registry.register({
  name: 'Bad kind registration', kind: 'LAB', address: 'x',
  host: { newHost: { id: 'atomic', name: 'Atomic' } }
}));
expectTypeError(() => registry.register({
  name: 'Atomic lookup fails', kind: 'lab', address: 'x', host: { id: 'atomic' }
}));

// Initial-host validation: container, record shape, values, own fields, symbols, duplicates.
for (const bad of [null, {}, 'x', 1]) expectTypeError(() => createWorkshopRegistry(bad));
for (const badHost of [
  null,
  [],
  'host',
  {},
  { id: 'x' },
  { name: 'x' },
  { id: '', name: 'x' },
  { id: 'x', name: '' },
  { id: 1, name: 'x' },
  { id: 'x', name: 1 },
  { id: 'x', name: 'y', extra: true }
]) expectTypeError(() => createWorkshopRegistry([badHost]));
const inheritedRequired = Object.create({ id: 'x' });
inheritedRequired.name = 'y';
expectTypeError(() => createWorkshopRegistry([inheritedRequired]));
const symbolInitial = { id: 'x', name: 'y' };
symbolInitial[Symbol('extra')] = true;
expectTypeError(() => createWorkshopRegistry([symbolInitial]));
expectRangeError(() => createWorkshopRegistry([
  { id: 'same', name: 'one' }, { id: 'same', name: 'two' }
]));
createWorkshopRegistry([{ id: 'same', name: 'one' }, { id: 'Same', name: 'two' }]);
createWorkshopRegistry([{ id: 'x', name: ' ' }]);

const validRegistry = createWorkshopRegistry([{ id: 'host', name: 'Host' }]);
function valid(overrides = {}) {
  return Object.assign({ name: 'Name', kind: 'lab', address: 'Address', host: { id: 'host' } }, overrides);
}

// Top-level registration validation and exact own-field schema.
for (const bad of [
  null,
  [],
  'x',
  {},
  valid({ name: '' }),
  valid({ name: 1 }),
  valid({ address: '' }),
  valid({ address: 1 }),
  valid({ kind: 'Lab' }),
  valid({ kind: 'workshop' }),
  valid({ host: null }),
  valid({ host: [] })
]) expectTypeError(() => validRegistry.register(bad));
for (const missing of ['name', 'kind', 'address', 'host']) {
  const value = valid();
  delete value[missing];
  expectTypeError(() => validRegistry.register(value));
}
expectTypeError(() => validRegistry.register(Object.assign(valid(), { extra: true })));
const symbolWorkshop = valid();
symbolWorkshop[Symbol('extra')] = true;
expectTypeError(() => validRegistry.register(symbolWorkshop));
const inheritedName = Object.create({ name: 'Inherited' });
Object.assign(inheritedName, { kind: 'lab', address: 'x', host: { id: 'host' } });
expectTypeError(() => validRegistry.register(inheritedName));

// Host selector requires exactly one exact own key and validates nested newHost strictly.
for (const host of [
  {},
  { id: 'host', newHost: { id: 'n', name: 'N' } },
  { id: 'host', extra: true },
  { id: '' },
  { id: 1 },
  { id: 'unknown' },
  { newHost: null },
  { newHost: [] },
  { newHost: {} },
  { newHost: { id: 'n' } },
  { newHost: { id: '', name: 'N' } },
  { newHost: { id: 'n', name: '' } },
  { newHost: { id: 1, name: 'N' } },
  { newHost: { id: 'n', name: 2 } },
  { newHost: { id: 'n', name: 'N', extra: true } }
]) expectTypeError(() => validRegistry.register(valid({ host })));
const inheritedId = Object.create({ id: 'host' });
expectTypeError(() => validRegistry.register(valid({ host: inheritedId })));
const symbolSelector = { id: 'host' };
symbolSelector[Symbol('extra')] = true;
expectTypeError(() => validRegistry.register(valid({ host: symbolSelector })));
const symbolNewHost = { id: 'n', name: 'N' };
symbolNewHost[Symbol('extra')] = true;
expectTypeError(() => validRegistry.register(valid({ host: { newHost: symbolNewHost } })));

// Non-enumerable required registration and selector fields are accepted.
const nonEnumerableRegistry = createWorkshopRegistry([hiddenHost('hidden', 'Hidden Host')]);
const selector = {};
Object.defineProperty(selector, 'id', { value: 'hidden', enumerable: false });
const hiddenWorkshop = {};
for (const [key, value] of Object.entries({
  name: 'Hidden fields', kind: 'kitchen', address: 'Somewhere', host: selector
})) Object.defineProperty(hiddenWorkshop, key, { value, enumerable: false });
assert.deepStrictEqual(nonEnumerableRegistry.register(hiddenWorkshop), {
  name: 'Hidden fields', kind: 'kitchen', address: 'Somewhere',
  host: { id: 'hidden', name: 'Hidden Host' }
});

