'use strict';

function assembleReaderProfile(readerId, readers, loans) {
  if (typeof readerId !== 'string' || readerId.trim() === '') {
    throw new TypeError('readerId must be a non-empty string after trimming');
  }
  if (!Array.isArray(readers) || !Array.isArray(loans)) {
    throw new TypeError('readers and loans must be arrays');
  }

  const requestedId = readerId.trim();
  let selected = null;

  for (const reader of readers) {
    if (reader === null || typeof reader !== 'object') {
      throw new TypeError('malformed reader');
    }

    const id = reader.id;
    const displayName = reader.displayName;
    if (typeof id !== 'string' || id.trim() === '' ||
        typeof displayName !== 'string' || displayName.trim() === '') {
      throw new TypeError('malformed reader');
    }

    if (selected === null && id.trim() === requestedId) {
      selected = { id: id.trim(), displayName: displayName.trim() };
    }
  }

  const activeTitles = [];
  for (const loan of loans) {
    if (loan === null || typeof loan !== 'object') {
      throw new TypeError('malformed loan');
    }

    const loanReaderId = loan.readerId;
    const title = loan.title;
    const returned = loan.returned;
    if (typeof loanReaderId !== 'string' || loanReaderId.length === 0 ||
        typeof title !== 'string' || title.length === 0 ||
        typeof returned !== 'boolean') {
      throw new TypeError('malformed loan');
    }

    if (selected !== null && loanReaderId.trim() === selected.id && returned === false) {
      activeTitles.push(title.trim());
    }
  }

  return selected === null ? null : {
    id: selected.id,
    displayName: selected.displayName,
    activeTitles
  };
}

module.exports = { assembleReaderProfile };

