'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['assembleReaderProfile']);
assert.strictEqual(typeof api.assembleReaderProfile, 'function');
const { assembleReaderProfile } = api;

function expectTypeError(fn) {
  assert.throws(fn, TypeError);
}

// Basic selection, trimming, active filtering, loan order, and duplicate titles.
const readers = [
  { id: ' other ', displayName: ' Other Reader ' },
  { id: ' reader-1 ', displayName: '  Alice Example  ' }
];
const loans = [
  { readerId: 'reader-1', title: ' First Book ', returned: false },
  { readerId: 'other', title: 'Ignored Active', returned: false },
  { readerId: ' reader-1 ', title: 'Returned Book', returned: true },
  { readerId: '\treader-1\n', title: 'Duplicate', returned: false },
  { readerId: 'reader-1', title: 'Duplicate', returned: false },
  { readerId: 'reader-1', title: '   ', returned: false }
];
assert.deepStrictEqual(assembleReaderProfile(' \treader-1\n ', readers, loans), {
  id: 'reader-1',
  displayName: 'Alice Example',
  activeTitles: ['First Book', 'Duplicate', 'Duplicate', '']
});

// Existing reader with no active loans gets an independent empty array.
const noActive = assembleReaderProfile('other', readers, [
  { readerId: 'other', title: 'Already Returned', returned: true },
  { readerId: 'someone-else', title: 'Active Elsewhere', returned: false }
]);
assert.deepStrictEqual(noActive, { id: 'other', displayName: 'Other Reader', activeTitles: [] });
const noActiveAgain = assembleReaderProfile('other', readers, []);
assert.notStrictEqual(noActive.activeTitles, noActiveAgain.activeTitles);

// A valid but absent ID returns null only after normal validation.
assert.strictEqual(assembleReaderProfile('missing', readers, loans), null);
assert.strictEqual(assembleReaderProfile('missing', [], []), null);

// Duplicate normalized reader IDs select the first reader.
const duplicateReaders = [
  { id: ' duplicate ', displayName: ' First ' },
  { id: 'duplicate', displayName: 'Second' }
];
assert.deepStrictEqual(assembleReaderProfile('\nduplicate\t', duplicateReaders, [
  { readerId: ' duplicate ', title: ' Loan ', returned: false }
]), {
  id: 'duplicate',
  displayName: 'First',
  activeTitles: ['Loan']
});

// Readable inherited fields, extra fields, symbols, and unusual prototypes are allowed.
const readerPrototype = { id: 'proto-id', displayName: ' Prototype Reader ' };
const inheritedReader = Object.create(readerPrototype);
inheritedReader.extra = true;
inheritedReader[Symbol('metadata')] = 1;
const loanPrototype = { readerId: ' proto-id ', title: ' Inherited Title ', returned: false };
const inheritedLoan = Object.create(loanPrototype);
inheritedLoan.extra = 'allowed';
const nullPrototypeLoan = Object.create(null);
nullPrototypeLoan.readerId = 'proto-id';
nullPrototypeLoan.title = ' Null Prototype ';
nullPrototypeLoan.returned = false;
assert.deepStrictEqual(assembleReaderProfile('proto-id', [inheritedReader], [inheritedLoan, nullPrototypeLoan]), {
  id: 'proto-id',
  displayName: 'Prototype Reader',
  activeTitles: ['Inherited Title', 'Null Prototype']
});

// Non-enumerable readable fields are valid.
const hiddenReader = {};
Object.defineProperties(hiddenReader, {
  id: { value: 'hidden-reader', enumerable: false },
  displayName: { value: ' Hidden Name ', enumerable: false }
});
const hiddenLoan = {};
Object.defineProperties(hiddenLoan, {
  readerId: { value: 'hidden-reader', enumerable: false },
  title: { value: ' Hidden Loan ', enumerable: false },
  returned: { value: false, enumerable: false }
});
assert.deepStrictEqual(assembleReaderProfile('hidden-reader', [hiddenReader], [hiddenLoan]), {
  id: 'hidden-reader', displayName: 'Hidden Name', activeTitles: ['Hidden Loan']
});

// Inputs are not mutated and output does not retain mutable aliases.
const immutableReader = Object.freeze({ id: ' frozen ', displayName: ' Frozen Reader ' });
const immutableLoan = Object.freeze({ readerId: 'frozen', title: ' Frozen Title ', returned: false });
const immutableReaders = Object.freeze([immutableReader]);
const immutableLoans = Object.freeze([immutableLoan]);
const detached = assembleReaderProfile('frozen', immutableReaders, immutableLoans);
assert.deepStrictEqual(detached, {
  id: 'frozen', displayName: 'Frozen Reader', activeTitles: ['Frozen Title']
});
detached.id = 'changed';
detached.displayName = 'changed';
detached.activeTitles[0] = 'changed';
detached.activeTitles.push('extra');
assert.deepStrictEqual(assembleReaderProfile('frozen', immutableReaders, immutableLoans), {
  id: 'frozen', displayName: 'Frozen Reader', activeTitles: ['Frozen Title']
});
assert.deepStrictEqual(immutableReaders, [immutableReader]);
assert.deepStrictEqual(immutableLoans, [immutableLoan]);

// readerId and collection boundaries.
for (const badId of [undefined, null, 0, {}, [], '', ' ', '\t\n']) {
  expectTypeError(() => assembleReaderProfile(badId, [], []));
}
for (const badReaders of [undefined, null, {}, 'array', new Set()]) {
  expectTypeError(() => assembleReaderProfile('id', badReaders, []));
}
for (const badLoans of [undefined, null, {}, 'array', new Set()]) {
  expectTypeError(() => assembleReaderProfile('id', [], badLoans));
}

// Every reader record and both required readable values are validated.
for (const badReader of [
  null,
  undefined,
  [],
  'reader',
  1,
  {},
  { id: 'id' },
  { displayName: 'Name' },
  { id: '', displayName: 'Name' },
  { id: ' ', displayName: 'Name' },
  { id: 1, displayName: 'Name' },
  { id: 'id', displayName: '' },
  { id: 'id', displayName: '\t' },
  { id: 'id', displayName: 1 }
]) expectTypeError(() => assembleReaderProfile('id', [badReader], []));

// Sparse array holes are invalid records.
const sparseReaders = new Array(1);
expectTypeError(() => assembleReaderProfile('id', sparseReaders, []));
const sparseLoans = new Array(1);
expectTypeError(() => assembleReaderProfile('id', [], sparseLoans));

// Every loan record and field is validated. Raw-nonempty whitespace IDs/titles are valid.
for (const badLoan of [
  null,
  undefined,
  [],
  'loan',
