import { MessageRelay, RelayRegistry } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function equalArray(actual: readonly string[], expected: readonly string[], message: string): void {
  assert(actual.length === expected.length, `${message}: length mismatch`);
  for (let index = 0; index < expected.length; index += 1) {
    equal(actual[index], expected[index], `${message} at ${index}`);
  }
}

function expectInvalidName(action: () => void): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof RangeError, 'blank name must throw RangeError');
    equal((error as RangeError).message, 'Invalid relay name', 'blank-name error message');
    return;
  }
  throw new Error('blank name did not throw');
}

{
  const relay = new MessageRelay();
  relay.broadcast('empty');

  const calls: string[] = [];
  relay.subscribe(message => calls.push(`first:${message}`));
  relay.subscribe(message => calls.push(`second:${message}`));
  relay.broadcast('hello');
  equalArray(calls, ['first:hello', 'second:hello'], 'broadcast order and first listener');
}

{
  const relay = new MessageRelay();
  const calls: string[] = [];
  const shared = (message: string): void => { calls.push(`shared:${message}`); };
  const removeFirst = relay.subscribe(shared);
  relay.subscribe(message => calls.push(`middle:${message}`));
  const removeSecond = relay.subscribe(shared);

  removeSecond();
  removeSecond();
  relay.broadcast('a');
  equalArray(calls, ['shared:a', 'middle:a'], 'second duplicate unsubscribe must remove its own registration');

  calls.length = 0;
  removeFirst();
  removeFirst();
  relay.broadcast('b');
  equalArray(calls, ['middle:b'], 'first duplicate unsubscribe must remain independent and idempotent');
}

{
  const relay = new MessageRelay();
  const calls: string[] = [];
  let removeCaptured = (): void => {};
  let added = false;

  relay.subscribe(message => {
    calls.push(`leader:${message}`);
    removeCaptured();
    if (!added) {
      added = true;
      relay.subscribe(value => calls.push(`late:${value}`));
    }
  });
  removeCaptured = relay.subscribe(message => calls.push(`captured:${message}`));

  relay.broadcast('one');
  equalArray(calls, ['leader:one', 'captured:one'], 'current broadcast must use its starting snapshot');

  calls.length = 0;
  relay.broadcast('two');
  equalArray(calls, ['leader:two', 'late:two'], 'subscription changes must affect later broadcasts');
}

{
  const relay = new MessageRelay();
  const calls: string[] = [];
  const marker = { reason: 'listener failure' };
  relay.subscribe(() => calls.push('before'));
  relay.subscribe(() => { throw marker; });
  relay.subscribe(() => calls.push('after'));

  let caught: unknown;
  try {
    relay.broadcast('x');
  } catch (error) {
    caught = error;
  }
  assert(caught === marker, 'broadcast must propagate the exact thrown value');
  equalArray(calls, ['before'], 'broadcast must stop immediately after a listener throws');
}

{
  const registry = new RelayRegistry();
  expectInvalidName(() => registry.install('', new MessageRelay()));
  expectInvalidName(() => registry.install(' \t\n ', new MessageRelay()));
  equal(registry.get('missing'), undefined, 'unknown relay');

  const first = new MessageRelay();
  const replacement = new MessageRelay();
  registry.install('main', first);
  assert(registry.get('main') === first, 'installed relay identity');
  registry.install('main', replacement);
  assert(registry.get('main') === replacement, 'install must replace an existing name');
}

