expectRatingError(() => new ExhibitController('bad', 'c', 'a', -0.01), 'rating below zero');
expectRatingError(() => new ExhibitController('bad', 'c', 'a', 5.01), 'rating above five');
expectRatingError(() => new ExhibitController('bad', 'c', 'a', Number.NaN), 'NaN rating');
expectRatingError(() => new ExhibitController('bad', 'c', 'a', Number.POSITIVE_INFINITY), 'infinite rating');

{
