  const high = new ExhibitController('high', 'c', 'a', 5);
  equal(low.rating, 0, 'lower rating boundary');
  equal(high.rating, 5, 'upper rating boundary');
}

{
  const controller = new ExhibitController('original-key', 'old caption', 'old art', 1);
  const events: string[] = [];
  controller.on('captionChanged', value => events.push(`caption:${value}`));
  controller.on('artworkChanged', value => events.push(`artwork:${value}`));
  controller.on('ratingChanged', value => events.push(`rating:${value}`));

