    () => controller.update({ key: 'ignored', caption: 'damaged', artwork: 'damaged', rating: Number.NEGATIVE_INFINITY }),
    'invalid update',
  );
  equal(controller.key, 'stable', 'invalid update key stability');
  equal(controller.caption, 'caption', 'invalid update caption atomicity');
  equal(controller.artwork, 'art', 'invalid update artwork atomicity');
  equal(controller.rating, 2, 'invalid update rating atomicity');
  equalArray(events, [], 'invalid update must emit no changes');
