  const controller = new ExhibitController('key', 'caption', 'art', 3);
  const first = controller.state;
  const second = controller.state;
  assert(first !== second, 'state must return a fresh object');
  (first as { caption: string; artwork: string; rating: number }).caption = 'external';
  (first as { caption: string; artwork: string; rating: number }).artwork = 'external';
  (first as { caption: string; artwork: string; rating: number }).rating = 0;
  equal(controller.caption, 'caption', 'state caption isolation');
  equal(controller.artwork, 'art', 'state artwork isolation');
  equal(controller.rating, 3, 'state rating isolation');
}

{
  const controller = new ExhibitController('key', 'start', 'art', 1);
  const calls: string[] = [];
  const shared = (value: string): void => { calls.push(`shared:${value}`); };
  const removeFirst = controller.on('captionChanged', shared);
  controller.on('captionChanged', value => calls.push(`middle:${value}`));
  const removeSecond = controller.on('captionChanged', shared);

