  calls.length = 0;
  removeFirst();
  removeFirst();
  controller.caption = 'two';
  equalArray(calls, ['middle:two'], 'unsubscribe must be idempotent');
}

{
  const controller = new ExhibitController('key', 'start', 'art', 1);
  const calls: string[] = [];
  let removeCaptured = (): void => {};
  let added = false;

  controller.on('captionChanged', value => {
    calls.push(`leader:${value}`);
    removeCaptured();
    if (!added) {
      added = true;
      controller.on('captionChanged', later => calls.push(`late:${later}`));
    }
  });
