Repair the complete TypeScript source below and return one corrected complete source file.

`OutlineTree` stores an immutable copy of a hierarchy. `replace` rejects blank IDs, duplicate IDs, and cyclic object references with `TypeError`; validation and copying must finish before existing state changes, after which expansion and selection are reset. Sibling and root ordering must be preserved. `toggle` returns `false` for an unknown ID; otherwise it toggles expansion and returns the new state. `visibleRows` returns a new frozen array containing new frozen row objects in preorder, including descendants only when each parent on their path is expanded. `select` returns `false` for an unknown ID; otherwise it stores the ID, synchronously notifies callbacks captured at the start of notification in subscription order, and returns `true`. Subscriptions are not immediate. Repeated registration of the same listener creates distinct subscriptions, and each idempotent unsubscribe function removes only its own registration. Additions and removals during notification affect only later selections. Input nodes, returned arrays, and rows must not alias mutable internal state.

Known-bad source:

export interface OutlineNode {
  readonly id: string;
  readonly label: string;
  readonly kind: string;
  readonly children?: readonly OutlineNode[];
}

export interface OutlineRow {
  readonly id: string;
  readonly label: string;
  readonly kind: string;
  readonly depth: number;
  readonly expanded: boolean;
  readonly selected: boolean;
}

type SelectionListener = (id: string) => void;

export class OutlineTree {
  private roots: OutlineNode[] = [];
  private readonly ids = new Set<string>();
  private readonly expanded = new Set<string>();
  private selectedId: string | null = null;
  private readonly listeners: SelectionListener[] = [];

  constructor(nodes: readonly OutlineNode[] = []) {
    this.replace(nodes);
  }

  replace(nodes: readonly OutlineNode[]): void {
    const ids = new Set<string>();
    const active = new WeakSet<object>();
    const clone = (node: OutlineNode): OutlineNode => {
      if (active.has(node)) throw new TypeError("Cyclic hierarchy");
      if (node.id.trim() === "" || ids.has(node.id)) throw new TypeError("Invalid or duplicate id");
      active.add(node);
      ids.add(node.id);
      const children = (node.children ?? []).map(clone);
      active.delete(node);
      return Object.freeze({ id: node.id, label: node.label, kind: node.kind, children: Object.freeze(children) });
    };
    const roots = nodes.map(clone);
    this.roots = roots;
    this.ids.clear();
    for (const id of ids) this.ids.add(id);
    this.expanded.clear();
    this.selectedId = null;
  }

  toggle(id: string): boolean {
    if (!this.ids.has(id)) return false;
    if (this.expanded.has(id)) this.expanded.delete(id);
    else this.expanded.add(id);
    return this.expanded.has(id);
  }

  visibleRows(): readonly OutlineRow[] {
    const rows: OutlineRow[] = [];
    const visit = (node: OutlineNode, depth: number): void => {
      rows.push(Object.freeze({
        id: node.id,
        label: node.label,
        kind: node.kind,
        depth,
        expanded: this.expanded.has(node.id),
        selected: this.selectedId === node.id
      }));
      if (this.expanded.has(node.id)) {
        for (const child of node.children ?? []) visit(child, depth + 1);
      }
    };
    for (const root of this.roots) visit(root, 0);
    return Object.freeze(rows);
  }

  select(id: string): boolean {
    if (!this.ids.has(id)) return false;
    this.selectedId = id;
    for (const listener of [...this.listeners]) listener(id);
    return true;
  }

  onSelection(listener: SelectionListener): () => void {
    this.listeners.push(listener);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const index = this.listeners.indexOf(listener);
      if (index >= 0) this.listeners.splice(index, 1);
    };
  }
}

