export interface OutlineNode {
  readonly id: string;
  readonly label: string;
  readonly kind: string;
  readonly children?: readonly OutlineNode[];
}

export interface OutlineRow {
  readonly id: string;
  readonly label: string;
  readonly kind: string;
  readonly depth: number;
  readonly expanded: boolean;
  readonly selected: boolean;
}

type SelectionListener = (id: string) => void;
type SelectionRegistration = { readonly listener: SelectionListener };

export class OutlineTree {
  private roots: OutlineNode[] = [];
  private readonly ids = new Set<string>();
  private readonly expanded = new Set<string>();
  private selectedId: string | null = null;
  private readonly listeners: SelectionRegistration[] = [];

  constructor(nodes: readonly OutlineNode[] = []) {
    this.replace(nodes);
  }

  replace(nodes: readonly OutlineNode[]): void {
    const ids = new Set<string>();
    const active = new WeakSet<object>();
    const clone = (node: OutlineNode): OutlineNode => {
      if (active.has(node)) throw new TypeError("Cyclic hierarchy");
      if (node.id.trim() === "" || ids.has(node.id)) throw new TypeError("Invalid or duplicate id");
      active.add(node);
      ids.add(node.id);
      const children = (node.children ?? []).map(clone);
      active.delete(node);
      return Object.freeze({ id: node.id, label: node.label, kind: node.kind, children: Object.freeze(children) });
    };
    const roots = nodes.map(clone);
    this.roots = roots;
    this.ids.clear();
    for (const id of ids) this.ids.add(id);
    this.expanded.clear();
    this.selectedId = null;
  }

  toggle(id: string): boolean {
    if (!this.ids.has(id)) return false;
    if (this.expanded.has(id)) this.expanded.delete(id);
    else this.expanded.add(id);
    return this.expanded.has(id);
  }

  visibleRows(): readonly OutlineRow[] {
    const rows: OutlineRow[] = [];
    const visit = (node: OutlineNode, depth: number): void => {
      rows.push(Object.freeze({
        id: node.id,
        label: node.label,
        kind: node.kind,
        depth,
        expanded: this.expanded.has(node.id),
        selected: this.selectedId === node.id
      }));
      if (this.expanded.has(node.id)) {
        for (const child of node.children ?? []) visit(child, depth + 1);
      }
    };
    for (const root of this.roots) visit(root, 0);
    return Object.freeze(rows);
  }

  select(id: string): boolean {
    if (!this.ids.has(id)) return false;
    this.selectedId = id;
    const snapshot = this.listeners.map(({ listener }) => listener);
    for (const listener of snapshot) listener(id);
    return true;
  }

  onSelection(listener: SelectionListener): () => void {
    const registration: SelectionRegistration = { listener };
    this.listeners.push(registration);
    let active = true;
    return () => {
