import { OutlineTree } from './solution';
import type { OutlineNode, OutlineRow } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function equalArray(actual: readonly string[], expected: readonly string[], message: string): void {
  assert(actual.length === expected.length, `${message}: length mismatch`);
  for (let index = 0; index < expected.length; index += 1) {
    equal(actual[index], expected[index], `${message} at ${index}`);
  }
}

function rowSignature(rows: readonly OutlineRow[]): string[] {
  return rows.map(row => `${row.id}|${row.label}|${row.kind}|${row.depth}|${row.expanded}|${row.selected}`);
}

function expectTypeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof TypeError, `${message}: expected TypeError`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

{
  const child = { id: 'child', label: 'Child', kind: 'leaf' };
  const children: OutlineNode[] = [child];
  const root = { id: 'root', label: 'Root', kind: 'group', children };
  const tree = new OutlineTree([root, { id: 'second', label: 'Second', kind: 'leaf' }]);

  root.label = 'Mutated root';
  child.label = 'Mutated child';
  children.push({ id: 'late', label: 'Late', kind: 'leaf' });

  equalArray(
    rowSignature(tree.visibleRows()),
    ['root|Root|group|0|false|false', 'second|Second|leaf|0|false|false'],
    'root ordering and input isolation',
  );

  equal(tree.toggle('missing'), false, 'unknown toggle');
  equal(tree.toggle('root'), true, 'expand known node');
  const expandedRows = tree.visibleRows();
  equalArray(
    rowSignature(expandedRows),
    ['root|Root|group|0|true|false', 'child|Child|leaf|1|false|false', 'second|Second|leaf|0|false|false'],
    'preorder visibility and copied child data',
  );
  assert(Object.isFrozen(expandedRows), 'visible row array must be frozen');
  for (const row of expandedRows) assert(Object.isFrozen(row), 'each visible row must be frozen');

  const anotherRows = tree.visibleRows();
  assert(anotherRows !== expandedRows, 'visibleRows must return a new array');
  assert(anotherRows[0] !== expandedRows[0], 'visibleRows must return new row objects');
  equal(tree.toggle('root'), false, 'collapse known node');
}

{
  const tree = new OutlineTree([
    {
      id: 'root',
      label: 'Root',
      kind: 'group',
      children: [{ id: 'child', label: 'Child', kind: 'leaf' }],
    },
  ]);
  tree.toggle('root');
  tree.select('child');

  expectTypeError(
    () => tree.replace([{ id: ' ', label: 'Blank', kind: 'leaf' }]),
    'blank id',
  );
  equalArray(
    rowSignature(tree.visibleRows()),
    ['root|Root|group|0|true|false', 'child|Child|leaf|1|false|true'],
    'blank-id failure must preserve all existing state',
  );

  expectTypeError(
    () => tree.replace([
      { id: 'duplicate', label: 'One', kind: 'leaf' },
      { id: 'duplicate', label: 'Two', kind: 'leaf' },
    ]),
    'duplicate id',
  );
  equalArray(
    rowSignature(tree.visibleRows()),
    ['root|Root|group|0|true|false', 'child|Child|leaf|1|false|true'],
    'duplicate-id failure must preserve state',
  );

