Repair the complete TypeScript source below and return one corrected complete source file.

The module exports `NavigationConfig`, `WorkReference`, `Destination`, `parseWorkReference`, and `returnDestination`. `parseWorkReference` accepts a query with or without a leading `?`. If `mockMode` is true it always returns `{ kind: 'case', id: 'sample-case' }` without parsing or decoding any query content. Otherwise, split pairs on `&` and split each nonempty pair at its first `=`. Both the name and value of every nonempty pair must be decoded, including irrelevant fields, duplicate tails, and fields appearing after a usable reference. Decode `+` as space and percent escapes with `decodeURIComponent`; malformed escapes anywhere must propagate as `URIError` before a reference is returned. For duplicate names, use the first nonempty trimmed value. A nonempty `case` value takes precedence over a nonempty `message` value regardless of query order. If neither exists, throw `URIError`. Empty queries are allowed but consequently fail unless mock mode is active.

`returnDestination` trims `messageId`. A nonempty value selects `messageDeskUrl` and text `Message desk`; undefined, empty, or blank selects `caseDeskUrl` and text `Case desk`. The selected URL must be nonblank after trimming or a `TypeError` is thrown. Returned data must not retain mutable configuration state, and configuration data must not be mutated.

Known-bad source:
```ts
export interface NavigationConfig {
  readonly mockMode: boolean;
  readonly caseDeskUrl: string;
  readonly messageDeskUrl: string;
}

export type WorkReference =
  | { readonly kind: "case"; readonly id: string }
  | { readonly kind: "message"; readonly id: string };

export interface Destination {
  readonly text: "Case desk" | "Message desk";
  readonly url: string;
}

function decodePart(value: string): string {
  return decodeURIComponent(value.replace(/\+/g, " "));
}

function firstValue(query: string, name: string): string | undefined {
  const source = query.startsWith("?") ? query.slice(1) : query;
  for (const pair of source.split("&")) {
    if (pair.length === 0) continue;
    const separator = pair.indexOf("=");
    const rawName = separator < 0 ? pair : pair.slice(0, separator);
    const rawValue = separator < 0 ? "" : pair.slice(separator + 1);
    if (decodePart(rawName) === name) {
      const value = decodePart(rawValue).trim();
      if (value.length > 0) return value;
    }
  }
  return undefined;
}

export function parseWorkReference(
  query: string,
  config: NavigationConfig,
): WorkReference {
  if (config.mockMode) return { kind: "case", id: "sample-case" };
  const caseId = firstValue(query, "case");
  if (caseId !== undefined) return { kind: "case", id: caseId };
  const messageId = firstValue(query, "message");
  if (messageId !== undefined) return { kind: "message", id: messageId };
  throw new URIError("query contains no work reference");
}

export function returnDestination(
  messageId: string | undefined,
  config: NavigationConfig,
): Destination {
  const useMessages = messageId !== undefined && messageId.trim().length > 0;
  const text = useMessages ? "Message desk" : "Case desk";
  const url = (useMessages ? config.messageDeskUrl : config.caseDeskUrl).trim();
  if (url.length === 0) throw new TypeError("selected destination URL is blank");
  return { text, url };
}
