import { parseWorkReference, returnDestination } from './solution';
import type { Destination, NavigationConfig, WorkReference } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) {
    throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
  }
}

function reference(actual: WorkReference, kind: 'case' | 'message', id: string, message: string): void {
  equal(actual.kind, kind, `${message}: kind`);
  equal(actual.id, id, `${message}: id`);
}

function destination(actual: Destination, text: 'Case desk' | 'Message desk', url: string, message: string): void {
  equal(actual.text, text, `${message}: text`);
  equal(actual.url, url, `${message}: url`);
}

function expectUriError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof URIError, `${message}: expected URIError`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

function expectTypeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof TypeError, `${message}: expected TypeError`);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const config: NavigationConfig = {
  mockMode: false,
  caseDeskUrl: ' https://example.test/cases ',
  messageDeskUrl: ' https://example.test/messages ',
};

reference(parseWorkReference('?case=case-1', config), 'case', 'case-1', 'leading question mark');
reference(parseWorkReference('message=message-1', config), 'message', 'message-1', 'query without question mark');
reference(parseWorkReference('?message=first&case=preferred', config), 'case', 'preferred', 'case precedence after message');
reference(parseWorkReference('?case=preferred&message=other', config), 'case', 'preferred', 'case precedence before message');
reference(parseWorkReference('?case=+&case=%20chosen%20&case=later', config), 'case', 'chosen', 'first nonempty duplicate');
reference(parseWorkReference('?message=&message=++&message=%20m%2B1%20', config), 'message', 'm+1', 'empty duplicates and decoding');
reference(parseWorkReference('?%63ase=value', config), 'case', 'value', 'decoded field name');
reference(parseWorkReference('?case=a=b=c', config), 'case', 'a=b=c', 'split pair at first equals sign');
reference(parseWorkReference('?irrelevant=decoded+value&case=ok', config), 'case', 'ok', 'irrelevant decoded field');

expectUriError(() => parseWorkReference('', config), 'empty query');
expectUriError(() => parseWorkReference('?', config), 'question-mark-only query');
expectUriError(() => parseWorkReference('?&&unused=value', config), 'query without reference');
expectUriError(() => parseWorkReference('?case=++&message=%20', config), 'only blank references');
expectUriError(() => parseWorkReference('?case=ok&unused=%E0%A4%A', config), 'malformed irrelevant value after usable reference');
expectUriError(() => parseWorkReference('?message=ok&%ZZ=value', config), 'malformed irrelevant name after usable reference');
expectUriError(() => parseWorkReference('?case=first&case=%E0%A4%A', config), 'malformed duplicate tail');
expectUriError(() => parseWorkReference('?unused=%ZZ&case=ok', config), 'malformed content before usable reference');

{
  const mock: NavigationConfig = { mockMode: true, caseDeskUrl: '', messageDeskUrl: '' };
  reference(parseWorkReference('?case=%ZZ&message=%E0%A4%A', mock), 'case', 'sample-case', 'mock mode bypasses all parsing');
  reference(parseWorkReference('', mock), 'case', 'sample-case', 'mock mode accepts empty query');
}

{
  destination(returnDestination(' message-id ', config), 'Message desk', 'https://example.test/messages', 'nonblank message id');
  destination(returnDestination(undefined, config), 'Case desk', 'https://example.test/cases', 'undefined message id');
  destination(returnDestination('', config), 'Case desk', 'https://example.test/cases', 'empty message id');
  destination(returnDestination(' \t\n ', config), 'Case desk', 'https://example.test/cases', 'blank message id');
}

expectTypeError(
  () => returnDestination(undefined, { mockMode: false, caseDeskUrl: ' \t ', messageDeskUrl: 'valid' }),
  'blank selected case URL',
);
expectTypeError(
  () => returnDestination('id', { mockMode: false, caseDeskUrl: 'valid', messageDeskUrl: '\n ' }),
  'blank selected message URL',
);

{
  const mutableConfig = {
